  function start(fresh=false){runToken++;if(fresh){progress[mode]=1;saveProgress()}const token=runToken,startAt=fresh?1:nextLevel();overlay.hidden=true;keys.clear();state={mode,live:true,level:startAt,score:0,streak:0,lives:3,time:0,objects:[],spawn:0,playerX:480,shake:0,parts:[],powerCharges:{}};configureLevel(state,startAt);awardPowerCharges(state,true);syncHud();updatePowerUI();document.body.classList.add('is-game-fullscreen');exitFullscreenButton.hidden=false;exitGameButton.hidden=false;canvas.focus({preventScroll:true});statusEl.textContent=`${titles[mode]} · Level ${startAt} of 100. ${levelGoalText()}`;requestAnimationFrame(resize);requestAnimationFrame(now=>loop(now,token))}
