  function levelGoalText(){if(!state)return'';if(mode==='noodle')return`catch ${state.goal} foods and avoid chili bombs`;if(mode==='match')return`match ${state.pairs} dish pairs · ${state.maxMoves-state.moves} moves left`;if(mode==='roadster')return`collect ${state.goalTokens} tokens in ${state.goalTime.toFixed(1)} seconds`;if(mode==='trailblazer')return`remember ${state.route.length} tiles · ${state.routeTime.toFixed(1)} seconds`;return`land ${state.goalHits} precise hits`}
