  function updatePowerUI(){const select=$('power-select'),button=$('power-button'),defs=powerDefs[mode],level=state?.level||1,current=selectedPower[mode];select.replaceChildren();for(const power of defs){const option=document.createElement('option');option.value=power.id;const locked=power.unlock>level,charges=state?.powerCharges?.[power.id]||0;option.textContent=locked?`${power.label} · unlock Level ${power.unlock}`:state?`${power.label} · ${charges} charge${charges===1?'':'s'}`:`${power.label} · ready at Level ${power.unlock}`;option.disabled=locked;select.append(option)}const firstAvailable=defs.find(power=>power.unlock<=level);if(!firstAvailable)return;const chosen=defs.find(power=>power.id===current&&power.unlock<=level)||firstAvailable;selectedPower[mode]=chosen.id;select.value=chosen.id;const charges=state?.powerCharges?.[chosen.id]||0;button.textContent=state?.awaitingNext?`Ready for Level ${state.level}`:state?`Use ${chosen.label} · ${charges} left`:`Choose a power-up during play`;button.disabled=!state?.live||charges<1}
