  function drawMatch(){const s=state,left=282,top=62,cell=90,gap=12;ctx.textAlign='center';ctx.fillStyle='#fff8d8';ctx.font='800 19px Inter';ctx.fillText(`${s.boss?'BOSS MATCH · ':''}LEVEL ${s.level}/100  ·  MATCH ${s.pairs} DISH PAIRS`,480,31);ctx.font='700 13px Inter';ctx.fillStyle='#e4f5c9';ctx.fillText(`${Math.max(0,s.maxMoves-s.moves)} MOVES LEFT`,480,51);for(let i=0;i<s.cards.length;i++){const row=Math.floor(i/4),col=i%4,x=left+col*(cell+gap),y=top+row*(cell+gap),open=s.time<s.previewUntil||s.flipped.includes(i)||s.matched.has(i)||s.peekUntil>s.time;ctx.save();ctx.shadowColor=s.matched.has(i)?'#f3e876':'#071d1855';ctx.shadowBlur=s.cursor===i?21:10;ctx.shadowOffsetY=5;const tile=ctx.createLinearGradient(x,y,x+cell,y+cell);tile.addColorStop(0,open?(s.matched.has(i)?'#c5f27c':'#fff1aa'):'#e94638');tile.addColorStop(1,open?(s.matched.has(i)?'#42b95f':'#f0c64e'):'#a6192e');ctx.fillStyle=tile;ctx.beginPath();ctx.roundRect(x,y,cell,cell,15);ctx.fill();ctx.shadowColor='transparent';ctx.lineWidth=s.cursor===i?5:2;ctx.strokeStyle=s.cursor===i?'#fff6a0':'#ffffffad';ctx.stroke();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=open?'43px system-ui':'700 31px Georgia,serif';ctx.fillStyle='#fff';if(open){const sprite=dishSprites[dishSpriteByEmoji[s.cards[i]]],size=cell*.67;if(sprite?.complete&&sprite.naturalWidth)ctx.drawImage(sprite,x+(cell-size)/2,y+(cell-size)/2,size,size);else ctx.fillText(s.cards[i],x+cell/2,y+cell/2+2)}else ctx.fillText('✦',x+cell/2,y+cell/2+2);ctx.restore()}ctx.textBaseline='alphabetic';if(s.time<s.previewUntil){ctx.fillStyle='#fff';ctx.font='700 14px Inter';ctx.fillText(`MEMORIZE THE BOARD · ${Math.ceil(s.previewUntil-s.time)}s`,480,520)}else{ctx.fillStyle='#fff';ctx.font='700 13px Inter';ctx.fillText('REMEMBER THEIR PLACES · MATCH TWO',480,520)}}
